// Test verisi: bir test hesabindan 05550000000'a bekleyen arkadaslik
// istegi gonderir (ekran goruntusu icin). Anon anahtar + normal giris;
// service-role yok.
import { createClient } from '@supabase/supabase-js'
import { readFileSync } from 'node:fs'

const env = Object.fromEntries(
  readFileSync('C:/Users/orcns/projects/cloud/mobil/.env', 'utf8')
    .split(/\r?\n/)
    .filter((s) => s.includes('='))
    .map((s) => s.split('=').map((p) => p.trim()))
)
const sb = createClient(env.EXPO_PUBLIC_SUPABASE_URL, env.EXPO_PUBLIC_SUPABASE_ANON_KEY)

const HEDEF = 'e9819ec3-ffe8-42a4-86ac-8706d0ce62e9' // 05550000000

for (const tel of ['+905550000001', '+905550000002']) {
  const { error: girisHatasi } = await sb.auth.signInWithPassword({ phone: tel, password: '[SIR-GIZLENDI]' })
  if (girisHatasi) { console.log(tel, 'giris hatasi:', girisHatasi.message); continue }
  const { error } = await sb.rpc('takip_istegi_gonder', { p_kullanici_id: HEDEF })
  console.log(tel, error ? 'hata: ' + error.message : 'istek gonderildi')
  await sb.auth.signOut()
  if (!error) break
}

