            >
              {ani.kisiAdi}
            </Text>
          ) : null}
          {ani.kisiAdi && altParcalar.length > 0 ? ' · ' : ''}
          {altParcalar.join(' · ')}
        </Text>

        {ani.notMetni ? <Text style={stiller.not}>{ani.notMetni}</Text> : null}

        {ani.fotografUrl ? (
          <Image
            source={{ uri: ani.fotografUrl }}
            style={stiller.fotograf}
            contentFit="cover"
            transition={150}
            testID="akis-fotografi"
          />
