        {silinebilir && !silOnayiAcik && (
          <Pressable
            onPress={() => onSilOnayi?.(ani.id)}
            hitSlop={8}
            accessibilityRole="button"
            accessibilityLabel={t('ortak.sil')}
          >
            <Text style={stiller.silAc}>{t('ortak.sil')}</Text>
          </Pressable>
        )}

