create or replace function public.fsq_aktarim_adimi()
returns void
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  v_baslangic timestamptz := clock_timestamp();
  v_bant record;
  v_adet integer;
  -- Medium compute'ta (1 GB shared_buffers) dilim buyutuldu.
  v_dilim constant double precision := 0.1;
begin
  if not pg_try_advisory_xact_lock(424242) then
    return;
  end if;
  loop
    exit when clock_timestamp() - v_baslangic > interval '50 seconds';
    select * into v_bant from public.fsq_aktarim_ilerleme where not bitti order by bant limit 1;
    exit when not found;
    v_adet := public.fsq_aktar(v_bant.simdiki, least(v_bant.simdiki + v_dilim, v_bant.lng1));
    update public.fsq_aktarim_ilerleme
       set simdiki = least(v_bant.simdiki + v_dilim, v_bant.lng1),
           eklenen = eklenen + v_adet,
           bitti = (v_bant.simdiki + v_dilim >= v_bant.lng1),
           guncellendi = now()
     where bant = v_bant.bant;
  end loop;
end;
$function$;
select cron.schedule('fsq-aktarim', '* * * * *', $$set statement_timeout = '0'; select public.fsq_aktarim_adimi();$$);

select (select json_agg(json_build_object('bant', bant, 'simdiki', simdiki, 'eklenen', eklenen, 'bitti', bitti, 'g', to_char(guncellendi, 'HH24:MI'))) from public.fsq_aktarim_ilerleme) as ilerleme,
       (select count(*) from public.mekanlar where kaynak='foursquare') as aktarilan,
       (select json_agg(json_build_object('durum', status, 'basladi', to_char(start_time,'HH24:MI:SS'), 'sure', (end_time-start_time)::text)) from (select * from cron.job_run_details where jobid=(select jobid from cron.job where jobname='fsq-aktarim') order by start_time desc limit 3) x) as kosumlar;

select (select json_agg(json_build_object('bant', bant, 'simdiki', simdiki, 'eklenen', eklenen, 'bitti', bitti)) from public.fsq_aktarim_ilerleme) as ilerleme,
       (select count(*) from public.mekanlar where kaynak='foursquare') as aktarilan,
       (select count(*) from public.fsq_hazirlik h where not h.islendi and not exists (select 1 from public.mekanlar m where m.fsq_place_id = h.fsq_place_id)) as kalan;

-- Foursquare tek kaynak - BITIS ADIMLARI (2026-08-30). Aktarim bitti
-- (5.980.471 satir). Sirayla: Overture silinir (check-in yapilmis
-- mekanlar haric), indeksler yeniden kurulur, hazirlik bosaltilir.
-- Her adim ayri cron kosumunda (uzun DDL'ler MCP/HTTP zaman asimina
-- takilmasin); durum tablosu ile ilerler, advisory lock ust uste
-- binmeyi keser.
select cron.unschedule('fsq-aktarim');

create table if not exists public.fsq_bitis (
  tek boolean primary key default true check (tek),
  adim integer not null default 1,
  not_ text,
  guncellendi timestamptz not null default now()
);
insert into public.fsq_bitis (adim) values (1) on conflict do nothing;
alter table public.fsq_bitis enable row level security;
revoke all on public.fsq_bitis from anon, authenticated;

create or replace function public.fsq_bitis_adimi()
returns void
language plpgsql
security definer
set search_path to 'public', 'extensions'
as $function$
declare
  v_adim integer;
  v_adet bigint;
begin
  if not pg_try_advisory_xact_lock(424243) then
    return;
  end if;
  select adim into v_adim from public.fsq_bitis;

  if v_adim = 1 then
    -- Overture silinir; check-in yapilmis mekanlar ve kullanici eklemeleri kalir.
    delete from public.mekanlar m
     where m.kaynak = 'overture'
       and not exists (select 1 from public.check_inler c where c.mekan_id = m.id);
    get diagnostics v_adet = row_count;
    update public.fsq_bitis set adim = 2, not_ = 'overture silindi: ' || v_adet, guncellendi = now();

  elsif v_adim = 2 then
    create index if not exists mekanlar_konum_idx on public.mekanlar using gist (konum);
    update public.fsq_bitis set adim = 3, not_ = 'konum indeksi kuruldu', guncellendi = now();

  elsif v_adim = 3 then
    create index if not exists mekanlar_ad_trgm_idx
      on public.mekanlar using gin (public.tr_kucuk(ad) extensions.gin_trgm_ops);
    update public.fsq_bitis set adim = 4, not_ = 'trgm indeksi kuruldu', guncellendi = now();

  elsif v_adim = 4 then
    create index if not exists mekanlar_tur_idx on public.mekanlar (tur);
    create index if not exists mekanlar_kategori_idx on public.mekanlar (kategori);
    update public.fsq_bitis set adim = 5, not_ = 'tur/kategori indeksleri kuruldu', guncellendi = now();

  elsif v_adim = 5 then
    truncate table public.fsq_hazirlik;
    update public.fsq_bitis set adim = 6, not_ = 'hazirlik bosaltildi; BITTI', guncellendi = now();
    perform cron.unschedule('fsq-bitis');
  end if;
end;
$function$;
revoke all on function public.fsq_bitis_adimi() from public, anon, authenticated;

select cron.schedule('fsq-bitis', '* * * * *', $$set statement_timeout = '0'; select public.fsq_bitis_adimi();$$);

