-- PostgREST'in on_conflict=fsq_place_id upsert'i KISMI tekil indeksle
-- eslesemiyor ("no unique or exclusion constraint matching"). Postgres
-- tam tekil indekste birden fazla NULL'a izin verdigi icin kismilige
-- gerek yok; indeks tam tekile cevrildi. (fsq_aktar'daki "where
-- fsq_place_id is not null" ozelligi de kaldirildi - tazelemede lazim.)
drop index if exists public.mekanlar_fsq_place_id_benzersiz;
create unique index mekanlar_fsq_place_id_benzersiz on public.mekanlar (fsq_place_id);

create or replace function public.fsq_aktar(p_lng0 double precision, p_lng1 double precision)
returns integer
language plpgsql
security definer
set search_path to 'public'
set statement_timeout to '1800s'
as $function$
declare v_adet integer;
begin
  insert into public.mekanlar (ad, tur, kategori, konum, adres, semt, kaynak, fsq_place_id)
  select f.ad, f.tur, f.kategori, f.konum, f.adres, f.semt, 'foursquare', f.fsq_place_id
  from public.fsq_hazirlik f
  where not f.islendi
    and ST_X(f.konum::geometry) >= p_lng0 and ST_X(f.konum::geometry) < p_lng1
  on conflict (fsq_place_id) do nothing;
  get diagnostics v_adet = row_count;
  return v_adet;
end;
$function$;

select (select count(*) from public.mekanlar where public.tr_kucuk(semt) in ('bursa','istanbul','izmir','ankara','turkiye')) as il_semt_kalan,
       (select count(*) from public.mekanlar where semt like '%/%') as bolulu_kalan,
       (select json_agg(json_build_object('sure',(now()-query_start)::text,'sorgu',left(query,40))) from pg_stat_activity where state='active' and pid<>pg_backend_pid()) as aktif;
